namespace sv_29cff4fc09fb4e818b6c36eb8a855f97.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_29cff4fc09fb4e818b6c36eb8a855f97.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="d-flex">
        <!-- Left Sidebar (Filters) -->
        <div class="pe-4" style="width: 25%; min-width: 220px;">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    <!-- Category checkboxes -->
                    <h6>Category</h6>
                    @if (_categories is null)
                    {
                        <div class="text-muted small mb-3">Loading categories…</div>
                    }
                    else
                    {
                        <div class="mb-3">
                            @foreach (var category in _categories)
                            {
                                <div class="form-check">
                                    <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                           checked="@(_selectedCategories.Contains(category))"
                                           @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                                    <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                                </div>
                            }
                        </div>
                    }

                    <!-- Price range -->
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label small mb-0">Min Price</label>
                        <input type="number" class="form-control form-control-sm" placeholder="0"
                               min="0" step="0.01" @bind="_minPrice" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label small mb-0">Max Price</label>
                        <input type="number" class="form-control form-control-sm" placeholder="Any"
                               min="0" step="0.01" @bind="_maxPrice" />
                    </div>

                    <!-- In Stock Only -->
                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="_inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    <!-- Filter buttons -->
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@_loading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@_loading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Main Content Area -->
        <div style="width: 75%;">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div class="d-flex align-items-center gap-2">
                    <label class="form-label mb-0 fw-semibold">Sort by:</label>
                    <select class="form-select form-select-sm" style="width: auto;" @bind="_sortBy" @bind:after="OnSortChangedAsync">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <div class="text-muted small">
                    @if (_result is not null && _result.TotalCount > 0)
                    {
                        var first = (_result.Page - 1) * _result.PageSize + 1;
                        var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        <span>Showing @first–@last of @_result.TotalCount products</span>
                    }
                </div>
            </div>

            <!-- Loading state -->
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading…</span>
                    </div>
                </div>
            }
            else if (_result is null || _result.TotalCount == 0)
            {
                <!-- Empty state -->
                <div class="text-center py-5 text-muted">
                    <h4>No products found</h4>
                    <p>Try adjusting your filters to find what you're looking for.</p>
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3 mb-4">
                    @foreach (var product in _result.Items)
                    {
                        <div class="col">
                            <div class="card h-100 product-card" role="button"
                                 @onclick="() => OnProductSelected.InvokeAsync(product.Id)"
                                 style="cursor: pointer;">
                                <!-- Placeholder image -->
                                <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
                                     style="height: 180px;" title="@product.Name">
                                    <span class="text-muted small">@product.Name</span>
                                </div>
                                <div class="card-body d-flex flex-column">
                                    <h6 class="card-title">@product.Name</h6>
                                    <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                    <p class="card-text mb-1">
                                        @GetStarRating(product.Rating)
                                    </p>
                                    @if (!product.InStock)
                                    {
                                        <span class="badge bg-danger mb-2" style="width: fit-content;">Out of Stock</span>
                                    }
                                    <div class="mt-auto">
                                        <button class="btn btn-sm btn-success w-100"
                                                disabled="@(!product.InStock)"
                                                @onclick="() => { }" @onclick:stopPropagation="true">
                                            Add to Cart
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    }
                </div>

                <!-- Pagination -->
                @{
                    var totalPages = (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
                }
                @if (totalPages > 1)
                {
                    <nav aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(_currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
                                        disabled="@(_currentPage == 1)">
                                    Previous
                                </button>
                            </li>
                            @for (var i = 1; i <= totalPages; i++)
                            {
                                var pageNum = i;
                                <li class="page-item @(pageNum == _currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(_currentPage == totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
                                        disabled="@(_currentPage == totalPages)">
                                    Next
                                </button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 9;

    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProductsAsync();

            _categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );

        _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        await ExecuteSearchAsync();
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        _sortBy = "price_asc";
        await ExecuteSearchAsync();
    }

    private async Task OnSortChangedAsync()
    {
        _currentPage = 1;
        await ExecuteSearchAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        _currentPage = page;
        await ExecuteSearchAsync();
    }

    private async Task ExecuteSearchAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        if (_categories is null)
        {
            await LoadInitialDataAsync();
        }
        else
        {
            await ExecuteSearchAsync();
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private static string GetStarRating(double rating)
    {
        var rounded = (int)Math.Round(rating);
        return new string('★', rounded) + new string('☆', 5 - rounded);
    }
}

